with latest as (select *, row_number() over (partition by manager_id order by hire_date desc nulls last, id asc) as rn from employees qualify rn = 1) select date_trunc('year', hire_date) as year_start, count(*) as num_rows, sum(salary) filter (where job_title = 'Intern') as intern_total_salary, count_if(level = 'L4') as l4_events, max(salary) filter (where level = 'L1') as l1_max_salary, count(*) filter (where level = 'L3') as l3_rows, sort_array(collect_set(level)) as level_list from latest group by 1 having l4_events > 1;
